+inline unsigned cstring_hash(const char* const& s) {
+  return java_lang_String::hash_code((const jbyte*)s, checked_cast<int>(strlen(s)));
+}
+
+inline bool cstring_equals(const char* const& a, const char* const& b) {
+  return strcmp(a, b) == 0;
+}
